// Source: js/i18n/i18n.js
const SUPPORTED_INTERFACE_LANGUAGES = new Set(['en', 'kn']);
const MESSAGE_CATALOGS = { en: EN_MESSAGES, kn: KN_MESSAGES };

class I18n {
  constructor(language = 'en', overrides = {}) {
    this.language = SUPPORTED_INTERFACE_LANGUAGES.has(language) ? language : 'en';
    this.setOverrides(overrides);
  }
  setOverrides(overrides = {}) {
    this.overrides = Object.fromEntries([...SUPPORTED_INTERFACE_LANGUAGES].map((language) => [
      language,
      Object.freeze({ ...(overrides[language] || {}) })
    ]));
  }
  setLanguage(language) {
    this.language = SUPPORTED_INTERFACE_LANGUAGES.has(language) ? language : 'en';
    document.documentElement.lang = this.language;
    this.apply();
  }
  t(key, values = {}) {
    const template = this.overrides[this.language]?.[key] ?? MESSAGE_CATALOGS[this.language][key] ?? this.overrides.en?.[key] ?? EN_MESSAGES[key] ?? key;
    return Object.entries(values).reduce((text, [name, value]) => text.replaceAll('{' + name + '}', value), template);
  }
  apply(root = document) {
    root.querySelectorAll('[data-i18n]').forEach((element) => { element.textContent = this.t(element.dataset.i18n); });
    root.querySelectorAll('[data-i18n-aria]').forEach((element) => element.setAttribute('aria-label', this.t(element.dataset.i18nAria)));
    root.querySelectorAll('[data-i18n-title]').forEach((element) => element.setAttribute('title', this.t(element.dataset.i18nTitle)));
  }
}

// Source: js/version-history.js
const DEFAULT_DB_NAME = 'gitaverse-version-history';
const DB_VERSION = 1;
const STORE = 'versions';

function versionHistoryRequestResult(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('Version history storage is unavailable.'));
  });
}

function openDatabase(databaseName = DEFAULT_DB_NAME) {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(databaseName, DB_VERSION);
    request.onupgradeneeded = () => {
      if (!request.result.objectStoreNames.contains(STORE)) request.result.createObjectStore(STORE, { keyPath: 'version' });
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('Version history storage is unavailable.'));
  });
}

function validateVersionHistory(records) {
  if (!Array.isArray(records)) throw new Error('Version history must be an array.');
  const seen = new Set();
  records.forEach((record, index) => {
    if (!record || typeof record !== 'object' || Array.isArray(record)) throw new Error(`Version history record ${index + 1} is invalid.`);
    if (!/^\d+\.\d{2}[A-Z][a-z]{2}\d{4}-\d{6}$/.test(record.version || '')) throw new Error(`Version history record ${index + 1} has an invalid version.`);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(record.date || '')) throw new Error(`Version history record ${index + 1} has an invalid date.`);
    if (!String(record.title || '').trim()) throw new Error(`Version history record ${index + 1} has no release title.`);
    if (record.message != null && typeof record.message !== 'string') throw new Error(`Version history record ${index + 1} has an invalid release message.`);
    if (seen.has(record.version)) throw new Error(`Version history contains duplicate version ${record.version}.`);
    seen.add(record.version);
  });
  return records;
}

function versionTimestamp(version) {
  const match = String(version).match(/\.(\d{2})([A-Z][a-z]{2})(\d{4})-(\d{2})(\d{2})(\d{2})$/);
  if (!match) return 0;
  const month = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'].indexOf(match[2]);
  return Date.UTC(Number(match[3]), month, Number(match[1]), Number(match[4]), Number(match[5]), Number(match[6]));
}

function releaseOrder(record) {
  const precise = [record.releasedAt, record.dateInstalled, record.dateSeen]
    .map((value) => Date.parse(value || ''))
    .find(Number.isFinite);
  if (Number.isFinite(precise)) return precise;
  const embedded = versionTimestamp(record.version);
  if (embedded) return embedded;
  const run = String(record.version || '').match(/^(\d+)\.(\d+)-(\d+)$/);
  if (run) return Number(run[1]) * 1e12 + Number(run[2]) * 1e4 + Number(run[3]);
  return Date.parse(`${record.date || '1970-01-01'}T00:00:00Z`) || 0;
}

function mergeVersionHistory(deployed = [], local = [], currentVersion = '', currentTitle = 'MyGita improvements and refinements') {
  const merged = new Map();
  deployed.forEach((record) => merged.set(record.version, { ...record }));
  local.forEach((record) => merged.set(record.version, { ...(merged.get(record.version) || {}), ...record }));
  if (currentVersion) {
    const current = merged.get(currentVersion) || {};
    merged.set(currentVersion, {
      version: currentVersion,
      date: current.date || new Date().toISOString().slice(0, 10),
      title: current.title || currentTitle,
      message: current.message || '',
      current: true,
      ...current
    });
  }
  return Array.from(merged.values()).sort((left, right) => {
    const dateOrder = String(right.date || '').localeCompare(String(left.date || ''));
    return dateOrder || releaseOrder(right) - releaseOrder(left);
  });
}

class VersionHistoryStore {
  constructor({ databaseName = DEFAULT_DB_NAME } = {}) {
    this.databaseName = databaseName;
    this.database = null;
  }
  async open() { if (!this.database) this.database = await openDatabase(this.databaseName); return this; }
  async recordSeen(version, at = new Date().toISOString()) { return this.record(version, 'dateSeen', at); }
  async recordInstalled(version, at = new Date().toISOString()) { return this.record(version, 'dateInstalled', at); }
  async record(version, field, at) {
    if (!version || version === 'dev') return null;
    await this.open();
    const transaction = this.database.transaction(STORE, 'readwrite');
    const store = transaction.objectStore(STORE);
    const existing = await versionHistoryRequestResult(store.get(version)) || { version };
    if (!existing[field]) existing[field] = at;
    store.put(existing);
    return existing;
  }
  async list() {
    await this.open();
    return versionHistoryRequestResult(this.database.transaction(STORE, 'readonly').objectStore(STORE).getAll());
  }
}

// Source: js/profile-store.js
const PROFILE_DB_VERSION = 4;
const PROFILE_STORE = 'profiles';
const SETTINGS_STORE = 'settings';
const RESUME_STORE = 'resumePoints';
const DIKSOOCHI_ENGAGEMENT_STORE = 'diksoochiEngagement';

function requestResult(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('The profile database could not be opened.'));
  });
}

function transactionDone(transaction) {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = resolve;
    transaction.onerror = () => reject(transaction.error || new Error('The profile change could not be saved.'));
    transaction.onabort = () => reject(transaction.error || new Error('The profile change was cancelled.'));
  });
}

function openProfileDatabase(databaseName) {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(databaseName, PROFILE_DB_VERSION);
    request.onupgradeneeded = (event) => {
      const database = request.result;
      const transaction = request.transaction;
      if (!database.objectStoreNames.contains(PROFILE_STORE)) {
        database.createObjectStore(PROFILE_STORE, { keyPath: 'pid', autoIncrement: true });
      }
      if (!database.objectStoreNames.contains(SETTINGS_STORE)) {
        database.createObjectStore(SETTINGS_STORE, { keyPath: 'key' });
      }
      if (!database.objectStoreNames.contains(RESUME_STORE)) {
        database.createObjectStore(RESUME_STORE, { keyPath: 'pid' });
      }
      if (!database.objectStoreNames.contains(DIKSOOCHI_ENGAGEMENT_STORE)) {
        const engagement = database.createObjectStore(DIKSOOCHI_ENGAGEMENT_STORE, { keyPath: 'key' });
        engagement.createIndex('pid', 'pid', { unique: false });
      }
      if (event.oldVersion < 3 && database.objectStoreNames.contains(PROFILE_STORE)) {
        const profiles = transaction.objectStore(PROFILE_STORE);
        profiles.openCursor().onsuccess = (event) => {
          const cursor = event.target.result;
          if (!cursor) return;
          const profile = cursor.value;
          const legacyLanguage = profile.language === 'kn' ? 'kn' : 'en';
          profile.interfaceLanguage = profile.interfaceLanguage === 'kn' ? 'kn' : legacyLanguage;
          profile.contentLanguage = profile.contentLanguage === 'kn' ? 'kn' : legacyLanguage;
          delete profile.language;
          cursor.update(profile);
          cursor.continue();
        };
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('Local profile storage is unavailable.'));
  });
}

function randomAnalyticsId() {
  if (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function') return globalThis.crypto.randomUUID();
  const bytes = new Uint8Array(16);
  globalThis.crypto.getRandomValues(bytes);
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
}

class ProfileStore {
  constructor({ databaseName = 'verses-local-profiles', languageModel = () => ({ content: ['en', 'kn'], interface: ['en', 'kn'] }) } = {}) {
    this.databaseName = databaseName;
    this.languageModel = languageModel;
    this.database = null;
  }

  async open() {
    if (!this.database) this.database = await openProfileDatabase(this.databaseName);
    return this;
  }

  async list() {
    await this.open();
    const transaction = this.database.transaction(PROFILE_STORE, 'readonly');
    const profiles = await requestResult(transaction.objectStore(PROFILE_STORE).getAll());
    return profiles.sort((left, right) => left.pid - right.pid);
  }

  async get(pid) {
    await this.open();
    if (!Number.isInteger(Number(pid))) return null;
    const transaction = this.database.transaction(PROFILE_STORE, 'readonly');
    return (await requestResult(transaction.objectStore(PROFILE_STORE).get(Number(pid)))) || null;
  }

  async save(input) {
    await this.open();
    const name = String(input.name || '').trim();
    if (!name) throw new Error('Enter a profile name.');
    const languages = this.languageModel();
    if (!languages.interface.includes(input.interfaceLanguage)) throw new Error('Choose an app language.');
    if (!languages.content.includes(input.contentLanguage)) throw new Error('Choose a preferred content language.');
    const now = new Date().toISOString();
    const existing = input.pid ? await this.get(input.pid) : null;
    const profile = {
      ...(existing || {}),
      name,
      dob: input.dob,
      gender: input.gender || '',
      interfaceLanguage: input.interfaceLanguage,
      contentLanguage: input.contentLanguage,
      photo: input.photo || '',
      analyticsConsent: Boolean(input.analyticsConsent),
      analyticsProfileId: existing?.analyticsProfileId || randomAnalyticsId(),
      createdAt: existing?.createdAt || now,
      updatedAt: now
    };
    delete profile.language;
    if (existing) profile.pid = existing.pid;
    const transaction = this.database.transaction(PROFILE_STORE, 'readwrite');
    const request = transaction.objectStore(PROFILE_STORE).put(profile);
    const pid = await requestResult(request);
    await transactionDone(transaction);
    return this.get(pid);
  }

  async remove(pid) {
    await this.open();
    const transaction = this.database.transaction([PROFILE_STORE, SETTINGS_STORE, RESUME_STORE, DIKSOOCHI_ENGAGEMENT_STORE], 'readwrite');
    transaction.objectStore(PROFILE_STORE).delete(Number(pid));
    const settings = transaction.objectStore(SETTINGS_STORE);
    const defaultPid = await requestResult(settings.get('defaultPid'));
    if (defaultPid && Number(defaultPid.value) === Number(pid)) settings.delete('defaultPid');
    settings.delete(`journeyView:${Number(pid)}`);
    settings.delete(`gitaSaraView:${Number(pid)}`);
    settings.delete(`selectedProduct:${Number(pid)}`);
    const panelPrefix = `panelLanguages:${Number(pid)}:`;
    const settingsCursor = settings.openCursor();
    settingsCursor.onsuccess = () => {
      const cursor = settingsCursor.result;
      if (!cursor) return;
      if (String(cursor.key).startsWith(panelPrefix)) cursor.delete();
      cursor.continue();
    };
    transaction.objectStore(RESUME_STORE).delete(Number(pid));
    const engagement = transaction.objectStore(DIKSOOCHI_ENGAGEMENT_STORE).index('pid');
    const engagementCursor = engagement.openKeyCursor(IDBKeyRange.only(Number(pid)));
    engagementCursor.onsuccess = () => {
      const cursor = engagementCursor.result;
      if (!cursor) return;
      transaction.objectStore(DIKSOOCHI_ENGAGEMENT_STORE).delete(cursor.primaryKey);
      cursor.continue();
    };
    await transactionDone(transaction);
  }

  async getResume(pid) {
    await this.open();
    if (!Number.isInteger(Number(pid))) return null;
    const transaction = this.database.transaction(RESUME_STORE, 'readonly');
    return (await requestResult(transaction.objectStore(RESUME_STORE).get(Number(pid)))) || null;
  }

  async getExperienceResume(pid, experience, product = '') {
    const record = await this.getResume(pid);
    const experienceId = String(experience || '');
    if (!record || !experienceId) return null;
    const productId = String(product || '');
    const saved = (productId && record.products?.[productId]?.experiences?.[experienceId]) || record.experiences?.[experienceId];
    if (saved?.sid) return { product: productId || saved.product, experience: experienceId, ...saved };
    // Records created before per-experience resume points are still usable.
    if (record.view === 'experience' && record.experience === experienceId && record.sid) {
      return {
        experience: experienceId,
        sid: record.sid,
        language: record.language,
        savedAt: record.savedAt
      };
    }
    return null;
  }

  async saveResume(resume) {
    await this.open();
    if (!Number.isInteger(Number(resume.pid))) throw new Error('A resume point requires a profile ID.');
    const pid = Number(resume.pid);
    const transaction = this.database.transaction(RESUME_STORE, 'readwrite');
    const store = transaction.objectStore(RESUME_STORE);
    const existing = await requestResult(store.get(pid));
    const record = {
      ...(existing || {}),
      pid,
      view: resume.view === 'experience' ? 'experience' : 'home',
      language: String(resume.language || this.languageModel().defaultContent || 'en'),
      savedAt: resume.savedAt || new Date().toISOString(),
      experiences: { ...(existing?.experiences || {}) },
      products: { ...(existing?.products || {}) }
    };
    if (record.view === 'experience') {
      record.experience = String(resume.experience || '');
      record.product = String(resume.product || '');
      record.sid = String(resume.sid || '');
      if (!record.experience || !record.sid) throw new Error('An experience resume point requires an experience and SID.');
      record.experiences[record.experience] = {
        sid: record.sid,
        language: record.language,
        savedAt: record.savedAt
      };
      if (record.product) {
        const productRecord = record.products[record.product] || { experiences: {} };
        productRecord.experiences = { ...(productRecord.experiences || {}), [record.experience]: {
          sid: record.sid,
          language: record.language,
          savedAt: record.savedAt
        } };
        productRecord.lastExperience = { experience: record.experience, sid: record.sid, language: record.language, savedAt: record.savedAt };
        record.products[record.product] = productRecord;
      }
      record.lastExperience = {
        product: record.product,
        experience: record.experience,
        sid: record.sid,
        language: record.language,
        savedAt: record.savedAt
      };
    } else {
      if (!record.lastExperience && existing?.view === 'experience' && existing.experience && existing.sid) {
        record.lastExperience = {
          experience: existing.experience,
          sid: existing.sid,
          language: String(existing.language || this.languageModel().defaultContent || 'en'),
          savedAt: existing.savedAt
        };
      }
      delete record.experience;
      delete record.sid;
      delete record.product;
    }
    store.put(record);
    await transactionDone(transaction);
    return record;
  }

  async defaultPid() {
    await this.open();
    const transaction = this.database.transaction(SETTINGS_STORE, 'readonly');
    const setting = await requestResult(transaction.objectStore(SETTINGS_STORE).get('defaultPid'));
    return setting ? Number(setting.value) : null;
  }

  async setDefaultPid(pid) {
    await this.open();
    const transaction = this.database.transaction(SETTINGS_STORE, 'readwrite');
    const store = transaction.objectStore(SETTINGS_STORE);
    if (pid == null) store.delete('defaultPid');
    else store.put({ key: 'defaultPid', value: Number(pid) });
    await transactionDone(transaction);
  }

  async getSelectedProduct(pid) {
    await this.open();
    if (!Number.isInteger(Number(pid))) return null;
    const transaction = this.database.transaction(SETTINGS_STORE, 'readonly');
    const setting = await requestResult(transaction.objectStore(SETTINGS_STORE).get(`selectedProduct:${Number(pid)}`));
    return typeof setting?.value === 'string' ? setting.value : null;
  }

  async setSelectedProduct(pid, productId) {
    await this.open();
    if (!Number.isInteger(Number(pid)) || !productId) return;
    const transaction = this.database.transaction(SETTINGS_STORE, 'readwrite');
    transaction.objectStore(SETTINGS_STORE).put({ key: `selectedProduct:${Number(pid)}`, value: String(productId) });
    await transactionDone(transaction);
  }

  async getPanelLanguages(pid, productId, experienceId) {
    await this.open();
    const key = `panelLanguages:${Number(pid)}:${String(productId)}:${String(experienceId)}`;
    const transaction = this.database.transaction(SETTINGS_STORE, 'readonly');
    const setting = await requestResult(transaction.objectStore(SETTINGS_STORE).get(key));
    return setting?.value && typeof setting.value === 'object' ? { ...setting.value } : {};
  }

  async setPanelLanguages(pid, productId, experienceId, value) {
    await this.open();
    const key = `panelLanguages:${Number(pid)}:${String(productId)}:${String(experienceId)}`;
    const transaction = this.database.transaction(SETTINGS_STORE, 'readwrite');
    const store = transaction.objectStore(SETTINGS_STORE);
    if (!value || !Object.keys(value).length) store.delete(key);
    else store.put({ key, value: { ...value } });
    await transactionDone(transaction);
  }

  async getJourneyView(pid) {
    await this.open();
    if (!Number.isInteger(Number(pid))) return null;
    const transaction = this.database.transaction(SETTINGS_STORE, 'readonly');
    const setting = await requestResult(transaction.objectStore(SETTINGS_STORE).get(`journeyView:${Number(pid)}`));
    return ['cards', 'table'].includes(setting?.value) ? setting.value : null;
  }

  async setJourneyView(pid, view) {
    await this.open();
    if (!Number.isInteger(Number(pid)) || !['cards', 'table'].includes(view)) return;
    const transaction = this.database.transaction(SETTINGS_STORE, 'readwrite');
    transaction.objectStore(SETTINGS_STORE).put({ key: `journeyView:${Number(pid)}`, value: view });
    await transactionDone(transaction);
  }

  async getGitaSaraView(pid) {
    await this.open();
    if (!Number.isInteger(Number(pid))) return null;
    const transaction = this.database.transaction(SETTINGS_STORE, 'readonly');
    const setting = await requestResult(transaction.objectStore(SETTINGS_STORE).get(`gitaSaraView:${Number(pid)}`));
    return ['two_panel', 'three_panel'].includes(setting?.value) ? setting.value : null;
  }

  async setGitaSaraView(pid, view) {
    await this.open();
    if (!Number.isInteger(Number(pid)) || !['two_panel', 'three_panel'].includes(view)) return;
    const transaction = this.database.transaction(SETTINGS_STORE, 'readwrite');
    transaction.objectStore(SETTINGS_STORE).put({ key: `gitaSaraView:${Number(pid)}`, value: view });
    await transactionDone(transaction);
  }

  async recordDiksoochiEngagement({ pid, experience, sid, chapter, seconds, occurredAt }) {
    await this.open();
    const profileId = Number(pid);
    if (!Number.isInteger(profileId) || !experience || !sid || !chapter) return;
    const key = `${profileId}:${experience}:${sid}`;
    const transaction = this.database.transaction(DIKSOOCHI_ENGAGEMENT_STORE, 'readwrite');
    const store = transaction.objectStore(DIKSOOCHI_ENGAGEMENT_STORE);
    const existing = await requestResult(store.get(key));
    store.put({
      ...(existing || {}), key, pid: profileId, experience, sid, chapter,
      firstMeaningfulAt: existing?.firstMeaningfulAt || occurredAt,
      lastMeaningfulAt: occurredAt,
      meaningfulVisitCount: (existing?.meaningfulVisitCount || 0) + (seconds === 10 ? 1 : 0),
      maxEngagementSeconds: Math.max(existing?.maxEngagementSeconds || 0, seconds)
    });
    await transactionDone(transaction);
  }

  async getDiksoochiSummary(pid) {
    await this.open();
    const transaction = this.database.transaction(DIKSOOCHI_ENGAGEMENT_STORE, 'readonly');
    const rows = await requestResult(transaction.objectStore(DIKSOOCHI_ENGAGEMENT_STORE).index('pid').getAll(Number(pid)));
    const meaningful = rows.filter((row) => row.meaningfulVisitCount > 0 || row.maxEngagementSeconds >= 10);
    return {
      chapters: new Set(meaningful.map((row) => row.chapter)).size,
      shlokas: new Set(meaningful.map((row) => row.sid)).size
    };
  }

  async getDiksoochiDetails(pid) {
    await this.open();
    const transaction = this.database.transaction(DIKSOOCHI_ENGAGEMENT_STORE, 'readonly');
    const rows = await requestResult(transaction.objectStore(DIKSOOCHI_ENGAGEMENT_STORE).index('pid').getAll(Number(pid)));
    const bySid = new Map();
    rows.filter((row) => row.meaningfulVisitCount > 0 || row.maxEngagementSeconds >= 10).forEach((row) => {
      const existing = bySid.get(row.sid) || { sid: row.sid, chapter: row.chapter, count: 0 };
      existing.count += Number(row.meaningfulVisitCount || (row.maxEngagementSeconds >= 10 ? 1 : 0));
      bySid.set(row.sid, existing);
    });
    return Array.from(bySid.values()).sort((left, right) => {
      const chapterDifference = Number(left.chapter) - Number(right.chapter);
      if (chapterDifference) return chapterDifference;
      const order = (value) => value === 'B' ? -1 : value === 'E' ? Number.MAX_SAFE_INTEGER : Number(value);
      return order(left.sid.split('.').pop()) - order(right.sid.split('.').pop());
    });
  }
}

async function resizeProfilePhoto(file) {
  if (!file) return '';
  if (!file.type.startsWith('image/')) throw new Error('Choose an image file for the profile photo.');
  const source = await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(new Error('The selected photo could not be read.'));
    reader.readAsDataURL(file);
  });
  const image = await new Promise((resolve, reject) => {
    const element = new Image();
    element.onload = () => resolve(element);
    element.onerror = () => reject(new Error('The selected photo is not a supported image.'));
    element.src = source;
  });
  const size = 256;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const context = canvas.getContext('2d');
  const scale = Math.max(size / image.width, size / image.height);
  const width = image.width * scale;
  const height = image.height * scale;
  context.drawImage(image, (size - width) / 2, (size - height) / 2, width, height);
  return canvas.toDataURL('image/jpeg', .82);
}

// Source: js/profile-ui.js
class ProfileUI {
  constructor({ store, onSelected, onCreated, onChanged, translate = (key, fallback) => fallback, onInterfaceLanguagePreview = () => {}, languageModel = () => null }) {
    this.store = store;
    this.onSelected = onSelected;
    this.onCreated = onCreated;
    this.onChanged = onChanged;
    this.translate = translate;
    this.onInterfaceLanguagePreview = onInterfaceLanguagePreview;
    this.languageModel = languageModel;
    this.editingPid = null;
    this.photo = '';
    this.bind();
  }

  initials(profile) {
    return profile.name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join('').toUpperCase() || 'ॐ';
  }

  avatar(profile, className = 'profile-avatar') {
    if (profile.photo) {
      const image = document.createElement('img');
      image.className = className;
      image.src = profile.photo;
      image.alt = '';
      return image;
    }
    const fallback = document.createElement('span');
    fallback.className = className + ' profile-initials';
    fallback.textContent = this.initials(profile);
    return fallback;
  }

  async showSelection({ switching = false } = {}) {
    const profiles = await this.store.list();
    const defaultPid = await this.store.defaultPid();
    const list = document.getElementById('profile-list');
    list.textContent = '';
    profiles.forEach((profile) => {
      const card = document.createElement('article');
      card.className = 'profile-card';
      const select = document.createElement('button');
      select.type = 'button';
      select.className = 'profile-select';
      select.dataset.pid = profile.pid;
      select.appendChild(this.avatar(profile, 'profile-card-avatar'));
      const copy = document.createElement('span');
      copy.className = 'profile-card-copy';
      const name = document.createElement('strong');
      name.textContent = profile.name;
      const language = document.createElement('small');
      const interfaceName = profile.interfaceLanguage === 'kn' ? 'ಕನ್ನಡ' : 'English';
      const contentName = this.languageModel()?.registry?.[profile.contentLanguage]?.nativeName || profile.contentLanguage;
      language.textContent = interfaceName + ' · ' + contentName;
      copy.append(name, language);
      select.appendChild(copy);
      if (profile.pid === defaultPid) {
        const badge = document.createElement('span');
        badge.className = 'default-badge';
        badge.textContent = this.translate('profile.defaultBadge', 'Default');
        select.appendChild(badge);
      }
      const actions = document.createElement('div');
      actions.className = 'profile-card-actions';
      actions.innerHTML = `<button type="button" data-profile-action="edit" data-pid="${profile.pid}">${this.translate('profile.editAction', 'Edit')}</button><button type="button" data-profile-action="default" data-pid="${profile.pid}">${profile.pid === defaultPid ? this.translate('profile.unsetDefault', 'Unset default') : this.translate('profile.makeDefault', 'Make default')}</button><button type="button" data-profile-action="delete" data-pid="${profile.pid}">${this.translate('profile.delete', 'Delete')}</button>`;
      card.append(select, actions);
      list.appendChild(card);
    });
    const selectionTitle = document.getElementById('profile-selection-title');
    selectionTitle.dataset.i18n = switching ? 'profile.switch' : 'profile.who';
    selectionTitle.textContent = switching ? this.translate('profile.switch', 'Switch profile') : this.translate('profile.who', 'Who is using Gitaverse?');
    document.getElementById('profile-selection-back').hidden = !switching;
  }

  async showForm(profile = null, { focusPreferences = false } = {}) {
    this.editingPid = profile?.pid || null;
    this.photo = profile?.photo || '';
    const formTitle = document.getElementById('profile-form-title');
    const formIntro = document.getElementById('profile-form-intro');
    formTitle.dataset.i18n = profile ? 'profile.edit' : 'profile.create';
    formIntro.dataset.i18n = profile ? 'profile.intro.edit' : 'profile.intro.create';
    formTitle.textContent = profile ? this.translate('profile.edit', 'Edit profile') : this.translate('profile.create', 'Create your profile');
    formIntro.textContent = profile
      ? this.translate('profile.intro.edit', 'Keep this profile’s local preferences up to date.')
      : this.translate('profile.intro.create', 'Profiles keep each person’s language and experience separate on this device.');
    document.getElementById('profile-name').value = profile?.name || '';
    document.getElementById('profile-dob').value = profile?.dob || '';
    document.getElementById('profile-gender').value = profile?.gender || '';
    document.getElementById('profile-interface-language').value = profile?.interfaceLanguage || '';
    const contentSelect = document.getElementById('profile-content-language');
    const model = this.languageModel();
    if (model) {
      contentSelect.replaceChildren(...model.content.map((language) => {
        const option = document.createElement('option'); option.value = language;
        option.textContent = model.registry[language]?.nativeName || model.registry[language]?.name || language;
        return option;
      }));
    }
    contentSelect.value = profile?.contentLanguage || model?.defaultContent || 'en';
    document.getElementById('profile-default').checked = profile ? (await this.store.defaultPid()) === profile.pid : true;
    document.getElementById('profile-form-cancel').hidden = !profile;
    document.getElementById('profile-form-error').textContent = '';
    this.renderPhotoPreview(profile);
    requestAnimationFrame(() => {
      const target = focusPreferences ? document.getElementById('profile-preferences-section') : document.getElementById('profile-name');
      target?.scrollIntoView({ block: focusPreferences ? 'center' : 'nearest', behavior: 'smooth' });
      target?.focus({ preventScroll: true });
    });
  }

  renderPhotoPreview(profile = null) {
    const preview = document.getElementById('profile-photo-preview');
    preview.textContent = '';
    preview.appendChild(this.avatar({ name: document.getElementById('profile-name').value || profile?.name || '', photo: this.photo }, 'profile-photo-avatar'));
    document.getElementById('profile-photo-remove').hidden = !this.photo;
  }

  async renderPills(profile) {
    document.querySelectorAll('[data-profile-pill]').forEach((button) => {
      button.textContent = '';
      const avatar = this.avatar(profile, 'profile-pill-avatar');
      if (button.classList.contains('topbar-profile-pill') && !profile.photo) {
        avatar.textContent = Array.from(profile.name.trim())[0]?.toUpperCase() || 'ॐ';
      }
      button.appendChild(avatar);
      const name = document.createElement('span');
      name.textContent = profile.name;
      if (!button.classList.contains('topbar-profile-pill')) button.appendChild(name);
      button.dataset.pid = profile.pid;
      button.setAttribute('aria-label', 'Profile: ' + profile.name + '. Open profile options.');
    });
  }

  bind() {
    document.getElementById('profile-form').addEventListener('submit', async (event) => {
      event.preventDefault();
      const error = document.getElementById('profile-form-error');
      error.textContent = '';
      try {
        if (!document.getElementById('profile-name').value.trim()) throw new Error(this.translate('validation.name', 'Enter a profile name.'));
        const dob = document.getElementById('profile-dob').value;
        if (!dob || new Date(dob + 'T00:00:00') > new Date()) throw new Error(this.translate('validation.dob', 'Enter a valid date of birth.'));
        const interfaceLanguage = document.getElementById('profile-interface-language').value;
        const contentLanguage = document.getElementById('profile-content-language').value;
        if (!interfaceLanguage) throw new Error(this.translate('validation.appLanguage', 'Choose an app language.'));
        if (!contentLanguage) throw new Error(this.translate('validation.contentLanguage', 'Choose a preferred Gita content language.'));
        const profile = await this.store.save({
          pid: this.editingPid,
          name: document.getElementById('profile-name').value,
          dob,
          gender: document.getElementById('profile-gender').value,
          interfaceLanguage,
          contentLanguage,
          photo: this.photo,
          analyticsConsent: true
        });
        if (document.getElementById('profile-default').checked) await this.store.setDefaultPid(profile.pid);
        else if ((await this.store.defaultPid()) === profile.pid) await this.store.setDefaultPid(null);
        if (this.editingPid) await this.onChanged(profile);
        else await this.onCreated(profile);
      } catch (failure) {
        error.textContent = failure.message || this.translate('validation.profileSave', 'The profile could not be saved.');
      }
    });
    document.getElementById('profile-name').addEventListener('input', () => this.renderPhotoPreview());
    document.getElementById('profile-interface-language').addEventListener('change', (event) => {
      const content = document.getElementById('profile-content-language');
      if (!this.editingPid && event.target.value) content.value = event.target.value;
      this.onInterfaceLanguagePreview(event.target.value || 'en');
    });
    document.getElementById('profile-photo').addEventListener('change', async (event) => {
      const error = document.getElementById('profile-form-error');
      try {
        this.photo = await resizeProfilePhoto(event.target.files?.[0]);
        this.renderPhotoPreview();
      } catch (failure) { error.textContent = failure.message; }
    });
    document.getElementById('profile-photo-remove').addEventListener('click', () => {
      this.photo = '';
      document.getElementById('profile-photo').value = '';
      this.renderPhotoPreview();
    });
    document.getElementById('profile-list').addEventListener('click', async (event) => {
      const select = event.target.closest('.profile-select');
      if (select) return this.onSelected(await this.store.get(select.dataset.pid));
      const action = event.target.closest('[data-profile-action]');
      if (!action) return;
      const profile = await this.store.get(action.dataset.pid);
      if (action.dataset.profileAction === 'edit') return this.onChanged(profile, { edit: true });
      if (action.dataset.profileAction === 'default') {
        const current = await this.store.defaultPid();
        await this.store.setDefaultPid(current === profile.pid ? null : profile.pid);
        return this.showSelection({ switching: true });
      }
      if (action.dataset.profileAction === 'delete' && window.confirm('Delete the profile “' + profile.name + '” from this device?')) {
        await this.store.remove(profile.pid);
        const remaining = await this.store.list();
        if (!remaining.length) return this.onChanged(null, { setup: true });
        return this.onChanged(null, { deletedPid: profile.pid, remaining });
      }
    });
  }
}

// Source: js/events/event-schema.js
const EVENT_SCHEMA_VERSION = 1;

const EVENT_NAMES = new Set([
  'app_opened',
  'profile_created',
  'profile_selected',
  'profile_updated',
  'profile_switched',
  'experience_selected',
  'location_changed',
  'language_changed',
  'home_opened',
  'data_load_failed',
  'profile_storage_failed',
  'pwa_update_available',
  'pwa_update_accepted',
  'pwa_update_dismissed',
  'pwa_update_completed',
  'pwa_update_failed',
  'verse_viewed',
  'verse_engaged_10s',
  'verse_engaged_30s',
  'verse_engaged_60s',
  'audio_started',
  'audio_resumed',
  'audio_paused',
  'audio_seeked',
  'audio_25',
  'audio_50',
  'audio_75',
  'audio_completed',
  'audio_failed',
  'gita_sara_view_changed',
  'rachana_opened',
  'rachana_page_viewed',
  'rachana_navigation_opened',
  'rachana_profile_selected',
  'rachana_about_opened',
  'rachana_gitaverse_opened',
  'rachana_document_failed'
]);

function validateEventInput(name, input = {}) {
  if (!EVENT_NAMES.has(name)) throw new Error('Unknown Gitaverse event: ' + name);
  if (input.context != null && (typeof input.context !== 'object' || Array.isArray(input.context))) {
    throw new Error('Event context must be an object.');
  }
  if (input.details != null && (typeof input.details !== 'object' || Array.isArray(input.details))) {
    throw new Error('Event details must be an object.');
  }
  if (name === 'location_changed') {
    if (!input.context?.experience || !input.context?.sid) {
      throw new Error('location_changed requires experience and sid.');
    }
  }
  if ((name === 'location_changed' || name === 'home_opened') && !Number.isInteger(Number(input.profileId))) {
    throw new Error(name + ' requires a profile ID.');
  }
  if (name === 'gita_sara_view_changed' && !['two_panel', 'three_panel'].includes(input.details?.view)) {
    throw new Error('gita_sara_view_changed requires an approved view.');
  }
}

function deepFreeze(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  Object.values(value).forEach(deepFreeze);
  return Object.freeze(value);
}

// Source: js/events/profile-analytics.js
const GENDERS = new Set(['female', 'male', 'nonbinary', 'self-described']);

function validDateParts(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value || ''));
  if (!match) return null;
  const [, year, month, day] = match.map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) return null;
  return { year, month, day };
}

function ageBand(dob, now = new Date()) {
  const birth = validDateParts(dob);
  if (!birth || Number.isNaN(now.getTime())) return 'missing';
  let age = now.getUTCFullYear() - birth.year;
  const month = now.getUTCMonth() + 1;
  const day = now.getUTCDate();
  if (month < birth.month || (month === birth.month && day < birth.day)) age -= 1;
  if (age < 0) return 'missing';
  if (age < 13) return 'unknown';
  if (age < 18) return '13-17';
  if (age < 25) return '18-24';
  if (age < 35) return '25-34';
  if (age < 45) return '35-44';
  if (age < 55) return '45-54';
  if (age < 65) return '55-64';
  if (age < 75) return '65-74';
  return '75-plus';
}

function profileAnalyticsContext(profile, now = new Date()) {
  if (!profile) return {};
  return {
    ageBand: ageBand(profile.dob, now),
    genderGroup: GENDERS.has(profile.gender) ? profile.gender.replace('-', '_') : 'not_said',
    profileLanguage: profile.interfaceLanguage === 'kn' ? 'kn' : 'en'
  };
}

// Source: js/events/event-bus.js
function randomId() {
  if (globalThis.crypto && typeof globalThis.crypto.randomUUID === 'function') return globalThis.crypto.randomUUID();
  const bytes = new Uint8Array(16);
  globalThis.crypto.getRandomValues(bytes);
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
}

class EventBus {
  constructor({ appVersion = 'dev', contextProvider = () => ({}), onAdapterError = () => {} } = {}) {
    this.appVersion = appVersion;
    this.contextProvider = contextProvider;
    this.onAdapterError = onAdapterError;
    this.sessionId = randomId();
    this.adapters = new Map();
  }

  subscribe(adapter) {
    if (!adapter?.id || typeof adapter.handle !== 'function') throw new Error('An event adapter requires an ID and handle function.');
    if (this.adapters.has(adapter.id)) throw new Error('Event adapter already registered: ' + adapter.id);
    this.adapters.set(adapter.id, adapter);
    return () => this.adapters.delete(adapter.id);
  }

  emit(name, input = {}) {
    validateEventInput(name, input);
    const event = deepFreeze({
      schemaVersion: EVENT_SCHEMA_VERSION,
      eventId: randomId(),
      event: name,
      occurredAt: new Date().toISOString(),
      sessionId: this.sessionId,
      profileId: input.profileId == null ? null : Number(input.profileId),
      anonymousProfileId: input.anonymousProfileId || null,
      context: {
        appVersion: this.appVersion,
        ...this.contextProvider(),
        ...(input.context || {})
      },
      details: { ...(input.details || {}) }
    });

    this.adapters.forEach((adapter) => {
      if (adapter.accepts && !adapter.accepts(event)) return;
      try {
        Promise.resolve(adapter.handle(event)).catch((error) => this.reportAdapterError(adapter, error, event));
      } catch (error) {
        this.reportAdapterError(adapter, error, event);
      }
    });
    return event;
  }

  reportAdapterError(adapter, error, event) {
    try { this.onAdapterError({ adapter: adapter.id, error, event }); } catch (_) {}
  }
}

// Source: js/events/analytics-event-map.js
const DIRECT_EVENTS = new Set([
  'app_opened', 'profile_created', 'profile_selected', 'profile_updated', 'profile_switched',
  'experience_selected', 'language_changed', 'home_opened', 'data_load_failed', 'profile_storage_failed',
  'pwa_update_available', 'pwa_update_accepted', 'pwa_update_dismissed', 'pwa_update_completed', 'pwa_update_failed',
  'verse_viewed', 'verse_engaged_10s', 'verse_engaged_30s', 'verse_engaged_60s',
  'audio_started', 'audio_resumed', 'audio_paused', 'audio_seeked', 'audio_25', 'audio_50',
  'audio_75', 'audio_completed', 'audio_failed', 'gita_sara_view_changed',
  'rachana_opened', 'rachana_page_viewed', 'rachana_navigation_opened', 'rachana_profile_selected',
  'rachana_about_opened', 'rachana_gitaverse_opened', 'rachana_document_failed'
]);

const LOCATION_EVENTS = {
  next: 'next_verse', previous: 'previous_verse', swipe: 'verse_swiped', goto: 'goto_verse',
  chapter: 'chapter_selected', resume: 'experience_resumed'
};

function present(value) { return value == null || value === '' ? undefined : value; }
function compact(values) { return Object.fromEntries(Object.entries(values).filter(([, value]) => value !== undefined)); }

function clarityEventName(event) {
  if (event.event === 'location_changed') return LOCATION_EVENTS[event.details.source] || null;
  return DIRECT_EVENTS.has(event.event) ? event.event : null;
}

function analyticsParameters(event) {
  const parameters = {
    age_band: present(event.context.ageBand), gender_group: present(event.context.genderGroup),
    interface_language: present(event.context.profileLanguage), content_language: present(event.context.language),
    product: present(event.context.distribution), experience: present(event.context.experience),
    collection: present(event.context.collection), verse_id: present(event.context.sid), chapter_id: present(event.context.chapter),
    app_version: present(event.context.appVersion), display_mode: present(event.context.displayMode),
    surface: present(event.context.surface), documentation_page: present(event.context.documentationPage)
  };
  if (event.event === 'location_changed') parameters.navigation_source = present(event.details.source);
  if (event.event.startsWith('pwa_update_')) {
    parameters.update_from_version = present(event.details.fromVersion);
    parameters.update_to_version = present(event.details.toVersion);
    parameters.update_result = present(event.details.result || event.details.stage);
  }
  if (event.event === 'gita_sara_view_changed') parameters.view = present(event.details.view);
  const engagement = event.event.match(/^verse_engaged_(10|30|60)s$/);
  if (engagement) parameters.engagement_seconds = Number(engagement[1]);
  const audioProgress = event.event.match(/^audio_(25|50|75)$/);
  if (audioProgress) parameters.progress_percent = Number(audioProgress[1]);
  if (event.event.startsWith('profile_') || event.event === 'rachana_profile_selected') parameters.profile_action = event.event;
  if (['data_load_failed', 'profile_storage_failed', 'audio_failed', 'rachana_document_failed'].includes(event.event)) parameters.error_type = event.event;
  return compact(parameters);
}

function googleAnalyticsParameters(event) {
  const { age_band, gender_group, ...parameters } = analyticsParameters(event);
  return parameters;
}

function googleAnalyticsEventName(event) {
  if (event.event === 'location_changed') return 'verse_navigated';
  if (event.event.startsWith('profile_') || event.event === 'rachana_profile_selected') return 'profile_action';
  if (event.event.startsWith('pwa_update_')) return 'pwa_update';
  if (/^verse_engaged_(10|30|60)s$/.test(event.event)) return 'verse_engaged';
  if (/^audio_(25|50|75)$/.test(event.event)) return 'audio_progress';
  if (['data_load_failed', 'profile_storage_failed', 'audio_failed', 'rachana_document_failed'].includes(event.event)) return 'app_error';
  if (event.event === 'rachana_page_viewed') return null;
  return DIRECT_EVENTS.has(event.event) ? event.event : null;
}

function analyticsPage(event) {
  if (event.event === 'home_opened') return { path: '/home', title: 'MyGita Home' };
  if (event.event === 'experience_selected' && event.context.experience) return { path: `/experience/${encodeURIComponent(event.context.experience)}`, title: `MyGita · ${event.context.experience}` };
  if (event.event === 'rachana_page_viewed' && event.context.documentationPage) return { path: `/rachana/${encodeURIComponent(event.context.documentationPage)}`, title: `Rachana · ${event.context.documentationPage}` };
  return null;
}

// Source: js/events/resume-adapter.js
class ResumeAdapter {
  constructor({ store }) {
    this.id = 'resume';
    this.store = store;
  }

  accepts(event) {
    return event.event === 'location_changed' || event.event === 'home_opened';
  }

  handle(event) {
    const base = {
      pid: event.profileId,
      language: event.context.language === 'kn' ? 'kn' : 'en',
      savedAt: event.occurredAt
    };
    if (event.context.product) base.product = event.context.product;
    if (event.event === 'home_opened') {
      return this.store.saveResume({ ...base, view: 'home' });
    }
    return this.store.saveResume({
      ...base,
      view: 'experience',
      experience: event.context.experience,
      sid: event.context.sid
    });
  }
}

// Source: js/events/diksoochi-adapter.js
class DiksoochiAdapter {
  constructor({ store }) {
    this.id = 'diksoochi';
    this.store = store;
  }

  accepts(event) {
    return /^verse_engaged_(10|30|60)s$/.test(event.event);
  }

  handle(event) {
    const seconds = Number(event.event.match(/(10|30|60)/)?.[1]);
    return this.store.recordDiksoochiEngagement({
      pid: event.profileId,
      experience: event.context.experience,
      sid: event.context.sid,
      chapter: event.context.chapter,
      seconds,
      occurredAt: event.occurredAt
    });
  }
}

// Source: js/events/clarity-adapter.js
class ClarityAdapter {
  constructor({ projectId = '', target = globalThis, documentRef = globalThis.document } = {}) {
    this.id = 'clarity';
    this.projectId = String(projectId || '').trim();
    this.target = target;
    this.document = documentRef;
    this.enabled = /^[a-z0-9]+$/i.test(this.projectId);
    this.started = false;
    this.tags = new Map();
  }

  accepts(event) {
    return this.enabled && (Boolean(event.context.ageBand) || event.event.startsWith('pwa_update_'));
  }

  initialize({ appVersion, displayMode }) {
    if (!this.enabled) return;
    this.start();
    this.setTag('app_version', appVersion);
    this.setTag('display_mode', displayMode);
  }

  start() {
    if (this.started) return;
    this.started = true;
    const clarity = this.target.clarity = this.target.clarity || function clarityQueue() {
      (clarity.q = clarity.q || []).push(arguments);
    };
    if (this.document?.querySelector(`script[data-clarity-project="${this.projectId}"]`)) return;
    const script = this.document.createElement('script');
    script.async = true;
    script.dataset.clarityProject = this.projectId;
    script.src = `https://www.clarity.ms/tag/${encodeURIComponent(this.projectId)}`;
    this.document.head.appendChild(script);
  }

  setTag(key, value) {
    if (value == null || value === '' || this.tags.get(key) === String(value)) return;
    this.tags.set(key, String(value));
    this.target.clarity('set', key, String(value));
  }

  handle(event) {
    this.start();
    const projected = analyticsParameters(event);
    const tags = {
      age_band: projected.age_band, gender_group: projected.gender_group,
      profile_language: projected.interface_language, experience: projected.experience,
      content_language: projected.content_language, app_version: projected.app_version,
      display_mode: projected.display_mode, surface: projected.surface,
      rachana_page: projected.documentation_page
    };
    Object.entries(tags).forEach(([key, value]) => this.setTag(key, value));
    if (event.event.startsWith('pwa_update_')) {
      this.setTag('update_from_version', event.details.fromVersion);
      this.setTag('update_to_version', event.details.toVersion);
      this.setTag('update_result', event.details.result || event.details.stage);
    }
    if (event.event === 'gita_sara_view_changed') this.setTag('gita_sara_view', event.details.view);

    const eventName = this.eventName(event);
    if (eventName) this.target.clarity('event', eventName);
  }

  eventName(event) {
    return clarityEventName(event);
  }
}

// Source: js/events/google-analytics-adapter.js
class GoogleAnalyticsAdapter {
  constructor({ measurementId = '', target = globalThis, documentRef = globalThis.document, locationRef = globalThis.location } = {}) {
    this.id = 'google-analytics';
    this.measurementId = String(measurementId || '').trim();
    this.target = target;
    this.document = documentRef;
    this.location = locationRef;
    this.enabled = /^G-[A-Z0-9]+$/i.test(this.measurementId);
    this.started = false;
  }

  accepts(event) {
    return this.enabled && Boolean(googleAnalyticsEventName(event) || analyticsPage(event));
  }

  initialize({ appVersion, displayMode }) {
    if (!this.enabled || this.started) return;
    this.started = true;
    const dataLayer = this.target.dataLayer = this.target.dataLayer || [];
    this.target.gtag = this.target.gtag || function googleTagQueue() { dataLayer.push(arguments); };
    this.target.gtag('js', new Date());
    this.target.gtag('config', this.measurementId, {
      send_page_view: false, allow_google_signals: false, allow_ad_personalization_signals: false,
      app_version: appVersion, display_mode: displayMode
    });
    if (!this.document?.querySelector(`script[data-ga-measurement-id="${this.measurementId}"]`)) {
      const script = this.document.createElement('script');
      script.async = true;
      script.dataset.gaMeasurementId = this.measurementId;
      script.src = `https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(this.measurementId)}`;
      this.document.head.appendChild(script);
    }
  }

  handle(event) {
    this.initialize({ appVersion: event.context.appVersion, displayMode: event.context.displayMode });
    const parameters = googleAnalyticsParameters(event);
    const eventName = googleAnalyticsEventName(event);
    if (eventName) this.target.gtag('event', eventName, parameters);
    const page = analyticsPage(event);
    if (page) this.target.gtag('event', 'page_view', {
      ...parameters, page_title: page.title, page_location: this.pageLocation(page.path)
    });
  }

  pageLocation(path) {
    const origin = /^https?:$/.test(this.location?.protocol || '') ? this.location.origin : 'https://mygita.gitajyoti.org';
    return new URL(path, origin).href;
  }
}

